INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_059571d9cf10d5c0d1f885f5','wiki/sources/uberblick-trassenanmeldung-zum-netzfahrplan-und-im-gelegenheitsverkehr.md',0,'Inhalt','**Trassenanmeldung im Netzfahrplan**

Die DB InfraGO AG konstruiert die Trassen des Netzfahrplans auf der Basis von Trassenanmeldungen. Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf.

Die jeweilige Trassenanmeldefristen für die Netzfahrpläne sind in Kapitel 4.2 der Nutzungsbedingungen Netz (NBN) genannt.

Die erforderlichen Anmeldeformulare und Leitfäden für die Trassenanmeldung im Netzfahrplan finden Sie [hier](https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/formulare-10907276).

**Trassenanmeldung im Gelegenheitsverkehr**

Bei Anmeldungen zum Gelegenheitsverkehr handelt es sich um:

- Anmeldungen außerhalb des Netzfahrplans bzw. außerhalb der Fristen des Netzfahrplans
- Änderungsanmeldungen zu Trassen des Netzfahrplans
- Änderungsanmeldungen zu Trassen des Gelegenheitsverkehrs

Trassen für den Gelegenheitsverkehr werden im Rahmen der vorhandenen freien Kapazitäten der Infrastruktur konstruiert. Um eine hochwertige, den Ansprüchen der Kund:innen genügende Trasse zu konstruieren, bedarf es detaillierter Angaben in der Trassenanmeldung wie zum Beispiel dem vorgesehenen Fahrzeugeinsatz, dem gewünschten Verkehrszeitraum und dem geplanten Fahrtverlauf.

Die erforderlichen Anmeldeformulare und Leitfäden für die Trassenanmeldung im Gelegenheitsverkehr finden Sie [hier](https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/formulare-10907276).',165,'{"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/ueberblick-10907392","normalized_sha256":"7fd9db8d5533ab30214d2ac05eff7c2c5c6bed0147989a4dff4a9d0e86d2a489","page":null,"source_id":"src_15a62986bf5cb9217f1c","source_sha256":"d1d89d8b90a962ba16dce9b22ae218e7b0ccd766b71ff68a904b7006e4d94e4b","source_version_id":"sv_7b15f5b01728d3b71a6f9897"}','9a64e7d680f6b6ffa7a497cf9263f581596254d078a918eb8a01013cb9ad85bc');
--> statement-breakpoint
INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) VALUES ('chunk_b3651ff6dfb9e3873a799a4e','wiki/sources/uberblick-trassenanmeldung-zum-netzfahrplan-und-im-gelegenheitsverkehr.md',1,'Inhalt','Die DB InfraGO AG stellt für die Trassenanmeldung das [**Trassenportal-Netz (TPN)**](https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/trassenportal-netz-11249618) zur Verfügung, das über eine Schnittstelle an interne IT-Systeme angebunden und auch aus dem Internet zugänglich ist. Die Nutzung des elektronischen Datenaustauschs ist zwischen der DB InfraGO AG und den Zugangsberechtigten zu vereinbaren. Für alle übrigen Fälle sind zur Erleichterung und Strukturierung der für die Trassenkonstruktion notwendigen Daten **verbindliche Formulare** aufgelegt. Werden für die Trassenanmeldungen Formulare verwendet, so können diese unter Verwendung eines elektronischen Datenträgers, per E-Mail oder über andere vereinbarte Kommunikationswege übermittelt werden. Mündliche oder fernmündliche Trassenanmeldungen sind in allen Fällen ausgeschlossen.

Trassenanmeldungen via E-Mail oder Fax richten Sie bitte an unsere nebenstehend genannten regionalen Trassenannahmestellen. Aktuell haben Sie die Möglichkeit, Ihre Trassenanmeldung den Ansprechpartner:innen in den Regionen zu übergeben, in deren sich der gewünschte Abgangsbahnhof befindet. Grundsätzlich startet dort die jeweilige Bearbeitung.',135,'{"canonical_url":"https://www.dbinfrago.com/web/schienennetz/leistungen/trassen/trassenbestellung/trassenanmeldung/ueberblick-10907392","normalized_sha256":"7fd9db8d5533ab30214d2ac05eff7c2c5c6bed0147989a4dff4a9d0e86d2a489","page":null,"source_id":"src_15a62986bf5cb9217f1c","source_sha256":"d1d89d8b90a962ba16dce9b22ae218e7b0ccd766b71ff68a904b7006e4d94e4b","source_version_id":"sv_7b15f5b01728d3b71a6f9897"}','216312cbe8203745eae69473dc0273589a290ee1289a554401d771b9b4641363');
--> statement-breakpoint
